CREATE TYPE "OrderIntentBrokerOpportunityApplicability" AS ENUM ('APPLICABLE_ACTIVE','APPLICABLE_SUPERSEDED','NOT_APPLICABLE_LIVE','NOT_APPLICABLE_UNENROLLED','NOT_APPLICABLE_UNKNOWN','NOT_APPLICABLE_LEGACY');
CREATE TYPE "OrderIntentBrokerOpportunityEventType" AS ENUM ('OPPORTUNITY_CAPTURED','ADAPTER_DISPATCH_REACHED','BROKER_RESPONSE_CONFIRMED','BROKER_REJECTED','DELIVERY_UNCERTAIN','DEFINITELY_NOT_SENT','DEFERRED','RECOVERY_FOUND','RECOVERY_ABSENCE_CONFIRMED','RECOVERY_INCONCLUSIVE','MISSING_OBSERVATION');

CREATE TABLE "OrderIntentBrokerOpportunityCaptureRollout" (id INTEGER PRIMARY KEY,enabled BOOLEAN NOT NULL DEFAULT false,"deployedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"effectiveEpoch" TIMESTAMPTZ(3),"disabledAt" TIMESTAMPTZ(3),"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "OrderIntentBrokerOpportunityCaptureRollout_singleton_check" CHECK(id=1),CONSTRAINT "OrderIntentBrokerOpportunityCaptureRollout_state_check" CHECK((enabled AND "effectiveEpoch" IS NOT NULL AND "disabledAt" IS NULL) OR (NOT enabled)));
CREATE TABLE "OrderIntentBrokerComparisonRollout" (id INTEGER PRIMARY KEY,enabled BOOLEAN NOT NULL DEFAULT false,"deployedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"effectiveEpoch" TIMESTAMPTZ(3),"disabledAt" TIMESTAMPTZ(3),"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "OrderIntentBrokerComparisonRollout_singleton_check" CHECK(id=1),CONSTRAINT "OrderIntentBrokerComparisonRollout_state_check" CHECK((enabled AND "effectiveEpoch" IS NOT NULL AND "disabledAt" IS NULL) OR (NOT enabled)));

CREATE FUNCTION "guard_broker_evidence_rollout"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.id<>1 OR OLD.id<>1 THEN RAISE EXCEPTION 'Broker evidence rollout is a singleton' USING ERRCODE='23514'; END IF;
 IF NOT OLD.enabled AND NEW.enabled THEN NEW."effectiveEpoch":=clock_timestamp(); NEW."disabledAt":=NULL;
 ELSIF OLD.enabled AND NOT NEW.enabled THEN NEW."effectiveEpoch":=OLD."effectiveEpoch"; NEW."disabledAt":=clock_timestamp();
 ELSIF NEW."effectiveEpoch" IS DISTINCT FROM OLD."effectiveEpoch" OR NEW."disabledAt" IS DISTINCT FROM OLD."disabledAt" THEN RAISE EXCEPTION 'Broker evidence rollout epochs are database-managed' USING ERRCODE='23514'; END IF;
 NEW."updatedAt":=statement_timestamp(); RETURN NEW; END $$;
CREATE TRIGGER "OrderIntentBrokerOpportunityCaptureRollout_guard" BEFORE UPDATE ON "OrderIntentBrokerOpportunityCaptureRollout" FOR EACH ROW EXECUTE FUNCTION "guard_broker_evidence_rollout"();
CREATE TRIGGER "OrderIntentBrokerComparisonRollout_guard" BEFORE UPDATE ON "OrderIntentBrokerComparisonRollout" FOR EACH ROW EXECUTE FUNCTION "guard_broker_evidence_rollout"();

CREATE TABLE "OrderIntentBrokerPostOpportunity" (
 id SERIAL PRIMARY KEY,"orderIntentId" INTEGER NOT NULL,"intentCoverageId" INTEGER NOT NULL,"tradingAccountId" INTEGER NOT NULL,"accountSubscriptionId" INTEGER NOT NULL,"enrollmentGenerationId" INTEGER,"policyRevisionId" INTEGER,"clientOrderId" TEXT NOT NULL,"opportunitySequence" INTEGER NOT NULL,"idempotencyKey" TEXT NOT NULL UNIQUE,"marketRegimeAssessmentId" INTEGER,"sourceSetFingerprint" TEXT,"compositionCapture" "OrderIntentMarketPolicyCompositionCapture" NOT NULL,applicability "OrderIntentBrokerOpportunityApplicability" NOT NULL,"comparisonMode" TEXT NOT NULL DEFAULT 'COMPARE_ONLY',"tradingEffect" TEXT NOT NULL DEFAULT 'NONE',"opportunityAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT "OrderIntentBrokerPostOpportunity_orderIntentId_fkey" FOREIGN KEY("orderIntentId") REFERENCES "OrderIntent"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT "OrderIntentBrokerPostOpportunity_intentCoverageId_fkey" FOREIGN KEY("intentCoverageId") REFERENCES "OrderIntentMarketPolicyCoverage"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT "OrderIntentBrokerPostOpportunity_tradingAccountId_fkey" FOREIGN KEY("tradingAccountId") REFERENCES "TradingAccount"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT "OrderIntentBrokerPostOpportunity_accountSubscriptionId_fkey" FOREIGN KEY("accountSubscriptionId") REFERENCES "TradingAccountSubscription"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT "OrderIntentBrokerPostOpportunity_enrollmentGenerationId_fkey" FOREIGN KEY("enrollmentGenerationId") REFERENCES "AssignmentMarketPolicyEnrollmentGeneration"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT "OrderIntentBrokerPostOpportunity_policyRevisionId_fkey" FOREIGN KEY("policyRevisionId") REFERENCES "StrategyMarketPolicyRevision"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT "OrderIntentBrokerPostOpportunity_marketRegimeAssessmentId_fkey" FOREIGN KEY("marketRegimeAssessmentId") REFERENCES "MarketRegimeAssessment"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT "OrderIntentBrokerPostOpportunity_intent_sequence_key" UNIQUE("orderIntentId","opportunitySequence"),
 CONSTRAINT "OrderIntentBrokerPostOpportunity_sequence_check" CHECK("opportunitySequence">0),
 CONSTRAINT "OrderIntentBrokerPostOpportunity_authority_check" CHECK("comparisonMode"='COMPARE_ONLY' AND "tradingEffect"='NONE'),
 CONSTRAINT "OrderIntentBrokerPostOpportunity_composition_check" CHECK(("compositionCapture"='EXACT' AND "marketRegimeAssessmentId" IS NOT NULL AND "sourceSetFingerprint" IS NOT NULL) OR ("compositionCapture"='NONE_VISIBLE' AND "marketRegimeAssessmentId" IS NULL AND "sourceSetFingerprint" IS NULL)),
 CONSTRAINT "OrderIntentBrokerPostOpportunity_applicability_check" CHECK((applicability IN ('APPLICABLE_ACTIVE','APPLICABLE_SUPERSEDED') AND "enrollmentGenerationId" IS NOT NULL AND "policyRevisionId" IS NOT NULL) OR (applicability NOT IN ('APPLICABLE_ACTIVE','APPLICABLE_SUPERSEDED') AND "enrollmentGenerationId" IS NULL AND "policyRevisionId" IS NULL))
);
CREATE INDEX "OrderIntentBrokerPostOpportunity_assignment_time_idx" ON "OrderIntentBrokerPostOpportunity"("accountSubscriptionId","opportunityAt");

CREATE FUNCTION "validate_broker_post_opportunity"() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE c "OrderIntentMarketPolicyCoverage"%ROWTYPE; i "OrderIntent"%ROWTYPE; env "TradingAccountEnvironment"; BEGIN
 SELECT * INTO c FROM "OrderIntentMarketPolicyCoverage" WHERE id=NEW."intentCoverageId"; SELECT * INTO i FROM "OrderIntent" WHERE id=NEW."orderIntentId"; SELECT environment INTO env FROM "TradingAccount" WHERE id=NEW."tradingAccountId";
 IF i.id IS NULL OR c.id IS NULL OR c."orderIntentId"<>i.id OR i.side<>'buy' OR i."clientOrderId" IS NULL OR NEW."clientOrderId"<>i."clientOrderId" OR ROW(NEW."tradingAccountId",NEW."accountSubscriptionId") IS DISTINCT FROM ROW(c."tradingAccountId",c."accountSubscriptionId") THEN RAISE EXCEPTION 'Broker opportunity identity is inconsistent' USING ERRCODE='23514'; END IF;
 IF NEW.applicability='APPLICABLE_ACTIVE' AND (env<>'PAPER' OR c.provenance<>'ACTIVE_EXACT') OR NEW.applicability='APPLICABLE_SUPERSEDED' AND (env<>'PAPER' OR c.provenance<>'SUPERSEDED_COMPARE_ONLY') THEN RAISE EXCEPTION 'Broker opportunity applicability is inconsistent' USING ERRCODE='23514'; END IF;
 IF NEW.applicability IN ('APPLICABLE_ACTIVE','APPLICABLE_SUPERSEDED') AND ROW(NEW."enrollmentGenerationId",NEW."policyRevisionId") IS DISTINCT FROM ROW(c."enrollmentGenerationId",c."boundPolicyRevisionId") THEN RAISE EXCEPTION 'Broker opportunity frozen policy identity is inconsistent' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER "OrderIntentBrokerPostOpportunity_validate" BEFORE INSERT ON "OrderIntentBrokerPostOpportunity" FOR EACH ROW EXECUTE FUNCTION "validate_broker_post_opportunity"();

CREATE TABLE "OrderIntentBrokerComparisonDelivery" (id SERIAL PRIMARY KEY,"opportunityId" INTEGER NOT NULL UNIQUE,status "OrderIntentMarketPolicyComparisonDeliveryStatus" NOT NULL DEFAULT 'PENDING',"attemptCount" INTEGER NOT NULL DEFAULT 0,"nextAttemptAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"leaseOwner" TEXT,"leaseExpiresAt" TIMESTAMPTZ(3),"lastErrorCode" TEXT,"completedAt" TIMESTAMPTZ(3),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "OrderIntentBrokerComparisonDelivery_opportunityId_fkey" FOREIGN KEY("opportunityId") REFERENCES "OrderIntentBrokerPostOpportunity"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT "OrderIntentBrokerComparisonDelivery_attempt_check" CHECK("attemptCount" BETWEEN 0 AND 3),CONSTRAINT "OrderIntentBrokerComparisonDelivery_state_check" CHECK((status='CLAIMED' AND "leaseOwner" IS NOT NULL AND "leaseExpiresAt" IS NOT NULL AND "completedAt" IS NULL) OR (status IN ('PENDING','RETRY_WAIT') AND "leaseOwner" IS NULL AND "leaseExpiresAt" IS NULL AND "completedAt" IS NULL) OR (status IN ('COMPLETED','TERMINAL_FAILURE') AND "leaseOwner" IS NULL AND "leaseExpiresAt" IS NULL AND "completedAt" IS NOT NULL)));
CREATE INDEX "OrderIntentBrokerComparisonDelivery_due_idx" ON "OrderIntentBrokerComparisonDelivery"(status,"nextAttemptAt"); CREATE INDEX "OrderIntentBrokerComparisonDelivery_lease_idx" ON "OrderIntentBrokerComparisonDelivery"("leaseExpiresAt");

CREATE TABLE "OrderIntentBrokerComparisonAttempt" (id SERIAL PRIMARY KEY,"opportunityId" INTEGER NOT NULL,attempt INTEGER NOT NULL,"enrollmentGenerationId" INTEGER NOT NULL,"policyRevisionId" INTEGER NOT NULL,"marketRegimeAssessmentId" INTEGER,"evidenceAsOf" TIMESTAMPTZ(3) NOT NULL,"evaluationVersion" TEXT NOT NULL,"enrollmentDisposition" TEXT NOT NULL,outcome "OrderIntentMarketPolicyComparisonOutcome" NOT NULL,"reasonCode" TEXT NOT NULL,authority TEXT NOT NULL DEFAULT 'COMPARE_ONLY',"tradingEffect" TEXT NOT NULL DEFAULT 'NONE',"evidenceJson" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OrderIntentBrokerComparisonAttempt_opportunityId_fkey" FOREIGN KEY("opportunityId") REFERENCES "OrderIntentBrokerPostOpportunity"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT "OrderIntentBrokerComparisonAttempt_authority_check" CHECK(authority='COMPARE_ONLY' AND "tradingEffect"='NONE'),CONSTRAINT "OrderIntentBrokerComparisonAttempt_attempt_check" CHECK(attempt BETWEEN 1 AND 3),CONSTRAINT "OrderIntentBrokerComparisonAttempt_disposition_check" CHECK("enrollmentDisposition" IN ('ACTIVE','SUPERSEDED_DIAGNOSTIC')),CONSTRAINT "OrderIntentBrokerComparisonAttempt_opportunity_attempt_key" UNIQUE("opportunityId",attempt));
CREATE UNIQUE INDEX "OrderIntentBrokerComparisonAttempt_completed_key" ON "OrderIntentBrokerComparisonAttempt"("opportunityId") WHERE outcome<>'TECHNICAL_FAILURE';
CREATE TABLE "OrderIntentBrokerComparisonGate" (id SERIAL PRIMARY KEY,"comparisonAttemptId" INTEGER NOT NULL,dimension "MarketRegimeDimension" NOT NULL,"algorithmVersion" TEXT NOT NULL,requirement "StrategyMarketPolicyDimensionRequirement" NOT NULL,outcome "StrategyMarketEligibilityGateOutcome" NOT NULL,"observedState" TEXT,"sourceHealth" "MarketRegimeCompositionSourceHealth","sourceAssessmentId" INTEGER,"allowedStatesJson" JSONB NOT NULL,"reasonCode" TEXT NOT NULL,"evidenceJson" JSONB NOT NULL,ordinal INTEGER NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OrderIntentBrokerComparisonGate_comparisonAttemptId_fkey" FOREIGN KEY("comparisonAttemptId") REFERENCES "OrderIntentBrokerComparisonAttempt"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT "OrderIntentBrokerComparisonGate_source_identity_fk" FOREIGN KEY("sourceAssessmentId",dimension,"algorithmVersion") REFERENCES "MarketRegimeDimensionAssessment"(id,dimension,"algorithmVersion") ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT "OrderIntentBrokerComparisonGate_ordinal_check" CHECK(ordinal BETWEEN 1 AND 5),CONSTRAINT "OrderIntentBrokerComparisonGate_attempt_dimension_key" UNIQUE("comparisonAttemptId",dimension),CONSTRAINT "OrderIntentBrokerComparisonGate_attempt_ordinal_key" UNIQUE("comparisonAttemptId",ordinal));

CREATE TABLE "OrderIntentBrokerOpportunityEvent" (id SERIAL PRIMARY KEY,"opportunityId" INTEGER NOT NULL,sequence INTEGER NOT NULL,"eventType" "OrderIntentBrokerOpportunityEventType" NOT NULL,"evidenceJson" JSONB NOT NULL,"occurredAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OrderIntentBrokerOpportunityEvent_opportunityId_fkey" FOREIGN KEY("opportunityId") REFERENCES "OrderIntentBrokerPostOpportunity"(id) ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT "OrderIntentBrokerOpportunityEvent_sequence_check" CHECK(sequence>0),CONSTRAINT "OrderIntentBrokerOpportunityEvent_opportunity_sequence_key" UNIQUE("opportunityId",sequence));

CREATE FUNCTION "validate_broker_comparison_attempt"() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE o "OrderIntentBrokerPostOpportunity"%ROWTYPE; BEGIN SELECT * INTO o FROM "OrderIntentBrokerPostOpportunity" WHERE id=NEW."opportunityId"; IF o.applicability NOT IN ('APPLICABLE_ACTIVE','APPLICABLE_SUPERSEDED') OR ROW(NEW."enrollmentGenerationId",NEW."policyRevisionId",NEW."marketRegimeAssessmentId",NEW."evidenceAsOf") IS DISTINCT FROM ROW(o."enrollmentGenerationId",o."policyRevisionId",o."marketRegimeAssessmentId",o."opportunityAt") OR NEW."enrollmentDisposition" IS DISTINCT FROM (CASE WHEN o.applicability='APPLICABLE_ACTIVE' THEN 'ACTIVE' ELSE 'SUPERSEDED_DIAGNOSTIC' END) OR (o."compositionCapture"='NONE_VISIBLE' AND (NEW.outcome<>'INSUFFICIENT_EVIDENCE' OR NEW."reasonCode"<>'NO_COMPOSITION_VISIBLE')) THEN RAISE EXCEPTION 'Broker comparison identity is inconsistent' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER "OrderIntentBrokerComparisonAttempt_validate" BEFORE INSERT ON "OrderIntentBrokerComparisonAttempt" FOR EACH ROW EXECUTE FUNCTION "validate_broker_comparison_attempt"();
CREATE FUNCTION "enforce_broker_comparison_gates"() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE n INTEGER; cap "OrderIntentMarketPolicyCompositionCapture"; BEGIN SELECT count(*) INTO n FROM "OrderIntentBrokerComparisonGate" WHERE "comparisonAttemptId"=NEW.id; SELECT "compositionCapture" INTO cap FROM "OrderIntentBrokerPostOpportunity" WHERE id=NEW."opportunityId"; IF (NEW.outcome='TECHNICAL_FAILURE' AND n<>0) OR (cap='NONE_VISIBLE' AND (NEW.outcome<>'INSUFFICIENT_EVIDENCE' OR n<>0)) OR (cap='EXACT' AND NEW.outcome<>'TECHNICAL_FAILURE' AND n<>5) THEN RAISE EXCEPTION 'Broker comparison attempt % has invalid gate completeness',NEW.id; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER "OrderIntentBrokerComparisonAttempt_gate_check" AFTER INSERT ON "OrderIntentBrokerComparisonAttempt" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "enforce_broker_comparison_gates"();
CREATE FUNCTION "prevent_broker_evidence_mutation"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% rows are immutable',TG_TABLE_NAME USING ERRCODE='23514'; END $$;
CREATE TRIGGER "OrderIntentBrokerPostOpportunity_immutable" BEFORE UPDATE OR DELETE ON "OrderIntentBrokerPostOpportunity" FOR EACH ROW EXECUTE FUNCTION "prevent_broker_evidence_mutation"();
CREATE TRIGGER "OrderIntentBrokerComparisonAttempt_immutable" BEFORE UPDATE OR DELETE ON "OrderIntentBrokerComparisonAttempt" FOR EACH ROW EXECUTE FUNCTION "prevent_broker_evidence_mutation"();
CREATE TRIGGER "OrderIntentBrokerComparisonGate_immutable" BEFORE UPDATE OR DELETE ON "OrderIntentBrokerComparisonGate" FOR EACH ROW EXECUTE FUNCTION "prevent_broker_evidence_mutation"();
CREATE TRIGGER "OrderIntentBrokerOpportunityEvent_immutable" BEFORE UPDATE OR DELETE ON "OrderIntentBrokerOpportunityEvent" FOR EACH ROW EXECUTE FUNCTION "prevent_broker_evidence_mutation"();
INSERT INTO "OrderIntentBrokerOpportunityCaptureRollout"(id,enabled,"updatedAt") VALUES(1,false,statement_timestamp()); INSERT INTO "OrderIntentBrokerComparisonRollout"(id,enabled,"updatedAt") VALUES(1,false,statement_timestamp());
